import type { Lesson } from "../lib/core";

const supabaseFoundation: Lesson = {
  id: "supabase-foundation",
  title: "Supabase Is Postgres Wearing an API Coat",
  volume: 6, module: 1, order: 1, level: "Full-Stack", status: "implemented", minutes: 50,
  summary: "Everything from Volume V is still true — Supabase is a PostgreSQL database you talk to over HTTP, plus Auth, Storage, and Realtime bolted on as extensions of the same trust model. This lesson maps the platform: roles, the two kinds of keys, the typed client, and local-first development.",
  prereqs: ["query-tuning"],
  objectives: [
    "Explain what Supabase adds to PostgreSQL — and what it does not replace",
    "Distinguish the anon, authenticated, and service_role database roles and who wears each",
    "Treat the publishable key as public and the service key as a root password",
    "Read a supabase-js call as a typed HTTP request against PostgREST",
    "Run a local project (CLI + migrations) and generate types from the live schema",
  ],
  concepts: ["PostgREST", "anon role", "authenticated role", "service_role", "publishable key", "generated types"],
  blocks: [
    { t: "lead", text: "A common first impression: 'Supabase is the open-source Firebase.' That framing gets the marketing right and the architecture wrong. The accurate sentence is: Supabase is a PostgreSQL database you already know how to design, fronted by an auto-generated HTTP API, with authentication, file storage, and realtime subscriptions implemented as first-class citizens of the same database. Nothing you learned in Volume V is obsolete — it is now the engine under the hood, and the skills transfer one-to-one." },
    { t: "why", text: ["**Why an API layer at all?** Volume IV taught you that browsers must never hold database credentials — so every app hand-built a REST API, wrote its auth, its validation, its connection pooling. Supabase's move: generate that API *from the schema itself* (PostgREST turns tables into endpoints) and enforce authorization *inside the database* (Row Level Security, next module). You keep full SQL power for the hard parts and get the boring 80% for free.", "**Why does this change your threat model?** Because the database is now reachable from the browser. Every query your client makes runs as a *role with limited rights* — and the boundary between 'what the browser may do' and 'what the server may do' becomes the most important line in your architecture. Get the keys wrong and the database is wide open; get RLS wrong and user A reads user B. This volume is the discipline for both."], },
    { t: "simple", text: ["Think of Supabase as **your PostgreSQL database hired a very strict receptionist**. The receptionist (the API layer) answers the phone for anyone with the public number — but every caller must state who they are, and the receptionist only lets them into the rooms the database's house rules allow. There's also a back door with a master key (the service key) that bypasses the receptionist entirely — which is exactly why it must never leave the staff office (your server)."], },
    { t: "model", title: "Three roles, two keys, one database", text: [
      "Every Supabase query runs as one of three PostgreSQL roles. **anon** — the anonymous caller: no login, minimal rights. **authenticated** — a logged-in user: the JWT from Supabase Auth maps to this role, and `auth.uid()` resolves to their id inside SQL. **service_role** — the master key: bypasses Row Level Security entirely, used only from trusted server code.",
      "The two keys mirror this split. The **publishable (anon) key** is public by design — it ships in browser bundles, and safety comes from RLS, not secrecy. The **service key** is a root password: it disables RLS for whoever holds it, so it lives only in environment variables on machines you control. Leaking it is not a bug; it is an incident with a rotation checklist.",
      "Everything else — Auth's users table, Storage's buckets and policies, Realtime's channel access — is implemented *in the same database*, using the same roles and the same policy language. One trust model, many surfaces. That unity is the idea the rest of the volume unpacks.",
    ], map: [
      ["A strict receptionist with a room list", "The API layer + RLS: public access, per-room rules"],
      ["The master key that opens every room", "service_role — powerful, and therefore never leaves the server"],
      ["The ID badge the receptionist checks", "The JWT: anon or authenticated, with auth.uid() inside"],
      ["One building, many entrances", "Auth, Storage, Realtime as rooms in the same Postgres"],
    ] },
    { t: "code", lang: "js", title: "A client call, translated", code: "// What you write:\nconst { data, error } = await supabase\n  .from(\"tasks\")\n  .select(\"id, title, done\")\n  .eq(\"user_id\", userId)\n  .order(\"created_at\", { ascending: false })\n  .limit(20);\n\n// What actually happens — an HTTP request against PostgREST:\n//   GET /rest/v1/tasks?select=id,title,done\n//       &user_id=eq.<userId>&order=created_at.desc&limit=20\n//   Authorization: Bearer <publishable key + user JWT>\n// The database runs it AS the authenticated role — and RLS\n// (next module) appends its own WHERE clause before a single\n// row is allowed to leave.\n// The filters you write are convenience; the policy is the law.", notes: ["Every method on the query builder maps to a URL parameter — which means the API surface is generated from your schema, not hand-written. Rename a column and the endpoint changes; the client stays type-safe if you regenerate types.", "error is not an exception: supabase-js returns { data, error }. Volume III's Result-pattern instinct applies directly — handle the fork, don't hope."], },
    { t: "code", lang: "bash", title: "Local-first: the project lives in Git, not in a dashboard", code: "# The CLI runs the whole platform in Docker on your machine:\nsupabase init            # creates supabase/config.toml\nsupabase start           # Postgres + Auth + Storage + PostgREST, locally\nsupabase migration new add_tasks\n# → supabase/migrations/20260214_add_tasks.sql\nsupabase db push         # apply migrations to a linked project\nsupabase gen types typescript --local > src/db/types.ts\n\n# The habit: schema changes are MIGRATION FILES, reviewed in PRs.\n# The dashboard SQL editor is for exploration — never the record of truth.", notes: ["Migrations are the schema's Git history — Volume II's lockfile discipline, applied to tables. A project whose schema lives only in dashboard clicks has no history, no review, and no rollback.", "Generated types keep client and schema honest: run gen types in CI and the build breaks the moment code and schema disagree."], },
    { t: "debug", title: "Debugging lab — 'the service key made it to the bundle'", scenario: "A code review flags that a component imports the client built with the service key 'just to make the query work' — RLS kept denying the insert. The fix shipped to production. Somewhere in the deployed JS, the master key is readable by anyone who opens DevTools.", error: "// The shortcut that became an incident:\nconst supabase = createClient(url, process.env.NEXT_PUBLIC_SERVICE_KEY!);\n//                                   ^^^^^^^^^^^^^^^^^^^^^^^\n// NEXT_PUBLIC_ means: baked into browser JavaScript.\n// The service key bypasses ALL Row Level Security.\n// Every visitor now holds a database root password.", tells: "Two smells compound here: 'RLS kept denying the insert' was the system working — a policy correctly refused a write — and the response was to escalate privilege instead of fixing the policy. Then the NEXT_PUBLIC_ prefix quietly exported the escalation to every browser. When a permission error's 'fix' is a bigger key, the key is the bug.", flow: ["Read the code — find every createClient call and ask which key each holds, and where that key's value is defined.", "Identify the layer — credential exposure, not query logic. Test: open the deployed bundle, search for the key's prefix (sb- / service_role).", "Reproduce — grep the build output; the key string is literally in the JS.", "Hypothesize — the real fix lives in the RLS policy that denied the insert (next module), not in privilege.", "Change one variable — rotate the service key FIRST (it's already public), then switch the client to the publishable key and repair the policy.", "Verify — the publishable client works under its policy; the old service key returns 401 everywhere."], root: "Publishable keys are safe because RLS limits them; service keys are lethal because they remove the limit. Putting a service key in client code converts a policy bug into total compromise — and NEXT_PUBLIC_ variables are, by name, public.", prevent: "House rules: the service key exists only in server-only env vars; CI greps bundles for key prefixes; every RLS denial is a policy ticket, never a privilege escalation." },
    { t: "mistake", title: "'It's just a backend-as-a-service, no SQL needed'", wrong: "Designing the app around dashboard tables and client-side cleverness, never opening psql or writing a migration.", right: "The database is still the source of truth: model it (Volume V), migrate it in files, query it directly when the builder gets awkward, and let RLS — real SQL — draw the security lines.", explain: "The abstraction is thin on purpose. Teams that treat Supabase as 'Firebase but Postgres' rediscover SQL during their first incident; teams that keep their PostgreSQL habits get the speed without the surprise." },
    { t: "note", kind: "security", title: "The key card, not the vault", text: ["Repeat until it's boring: the publishable key is not a secret. It is a room card that says 'anonymous caller' or 'this specific user' — and the building decides what that card opens. Security comes from RLS policies being correct, which is why the next two lessons treat policies with the same seriousness as password hashing. If your safety depends on the anon key staying hidden, you have no safety."], },
    { t: "note", kind: "production", title: "Connection pooling is built in — and transaction mode has rules", text: ["Supabase fronts Postgres with a pooler (Supavisor). Interactive client traffic is fine; long-running servers should connect through the pooler's transaction-mode port — and remember Volume V's rule: under transaction-mode pooling, a transaction pins a connection until COMMIT, so keep transactions short and never hold one open across a network call."], },
    { t: "try", title: "Try it yourself", steps: ["Run supabase init && supabase start on a scratch project; open the local Studio and confirm Postgres, Auth, and Storage are all containers in ONE compose file — one database, many rooms.", "Write a migration creating tasks(id, user_id, title, done, created_at) with a foreign key to auth.users — the table Auth gives you. Apply it locally and regenerate types.", "Call .from('tasks').select('*') from a browser script with the publishable key and no login. Record exactly what comes back and what the error says — that empty/denied answer is RLS's default posture, and you'll explain it next module.", "Stretch: inspect the network tab during the call and write out the REST URL it maps to. Which parts are your query builder's doing, and which part is the Authorization header?"] },
    { t: "quiz", title: "Check your understanding", questions: [
      { id: "q1", type: "single", prompt: "The publishable (anon) key is safe to ship in browser code because…", options: ["it is encrypted at rest", "safety comes from Row Level Security limiting what the anon/authenticated roles may do — the key itself is not a secret", "it expires after an hour", "browsers hide it from DevTools"], answer: [1], explain: "The key identifies the caller; RLS decides what that caller may touch. If your security depended on the key's secrecy, opening DevTools would end it — so it doesn't.", tags: ["supabase-foundation"] },
      { id: "q2", type: "single", prompt: "The service_role key differs from the publishable key because it…", options: ["has a longer expiration", "bypasses Row Level Security entirely — a root password for the database", "works only over HTTPS", "is rate-limited more strictly"], answer: [1], explain: "service_role disables RLS for its holder. That's why it exists (backups, admin jobs, auth webhooks) and why it must never reach a browser: it is total access by design.", tags: ["supabase-foundation"] },
      { id: "q3", type: "single", prompt: "When a logged-in user queries through supabase-js, the database executes the query as…", options: ["the postgres superuser", "the anon role", "the authenticated role, with auth.uid() resolving to their id", "service_role, then filters in JavaScript"], answer: [2], explain: "The JWT maps to the authenticated role; auth.uid() is how policies and queries know WHO. Filtering client-side after fetching everything as service_role is the exact anti-pattern this volume exists to prevent.", tags: ["supabase-foundation", "rls-first-principles"] },
      { id: "q4", type: "multi", prompt: "Select ALL practices that belong in a professional Supabase workflow.", options: ["Schema changes as migration files in Git", "Generated TypeScript types regenerated (or checked) in CI", "Dashboard SQL edits as the official schema record", "The service key restricted to server-only environment variables"], answer: [0, 1, 3], explain: "Migrations give the schema history and review; generated types keep client and schema honest; the service key stays server-side. Dashboard edits are exploration — without a migration file, the change doesn't officially exist.", tags: ["supabase-foundation"] },
      { id: "q5", type: "boolean", prompt: "Supabase replaces PostgreSQL — you no longer need SQL skills.", options: ["True", "False"], answer: [1], explain: "False — Supabase IS PostgreSQL plus an API coat. Modeling, constraints, policies, and performance are all still SQL work; the platform automates the transport, not the thinking.", tags: ["supabase-foundation"] },
    ] },
    { t: "vocab", terms: [["PostgREST", "The layer that turns tables into REST endpoints and runs client queries as limited database roles."], ["anon role", "The database identity of anonymous callers — minimal rights by default."], ["authenticated role", "The identity of logged-in users; auth.uid() resolves to their id inside SQL."], ["service_role", "The privileged role that bypasses RLS; server-only, treated as a root password."], ["Publishable key", "The public key shipped to browsers; safe only because RLS limits it."], ["Generated types", "TypeScript types produced from the live schema, keeping queries type-safe end to end."]] },
    { t: "recap", items: ["Supabase = your PostgreSQL database + generated API + Auth/Storage/Realtime as rooms in the same building.", "Three roles (anon/authenticated/service_role), two keys (public by design / private by necessity).", "Client calls are typed HTTP requests; RLS appends the real WHERE clause before any row leaves.", "Schema lives in migration files; types are generated; the dashboard explores, Git records.", "A permission error answered with a bigger key is the signature of a security incident in progress."] },
    { t: "checkpoint", text: "Explain why the publishable key is safe and the service key is lethal in two sentences — then name where each of the three roles appears in a typical request. Clean? Mark complete." },
    { t: "bridge", text: "The building has a receptionist and a master key — now meet the house rules. Next: Supabase Auth (who gets a badge), Storage and Realtime (rooms with their own locks), and how auth.uid() becomes the hinge the whole security model swings on.", next: "supabase-auth-storage" },
  ],
};

const supabaseAuthStorage: Lesson = {
  id: "supabase-auth-storage",
  title: "Auth, Storage, and Realtime: Rooms in the Same Building",
  volume: 6, module: 1, order: 2, level: "Full-Stack", status: "implemented", minutes: 55,
  summary: "Supabase Auth is a users table plus session machinery you never hand-roll; Storage is buckets guarded by the same policy language; Realtime is subscriptions authorized per row. The hinge for all three is auth.uid() — and the profiles-table pattern that connects identity to your data.",
  prereqs: ["supabase-foundation"],
  objectives: [
    "Model authentication as: users table + sessions + a JWT the database can read",
    "Choose email/password vs magic link vs OAuth deliberately, and handle the session lifecycle",
    "Connect identity to domain data with the profiles pattern and an auth.uid() foreign key",
    "Guard Storage buckets with policies, and upload through the authorized path",
    "Subscribe to Realtime changes only for rows the subscriber may already read",
  ],
  concepts: ["auth.users", "auth.uid()", "magic link", "OAuth", "profiles table", "storage policies", "realtime authorization"],
  blocks: [
    { t: "lead", text: "Volume IV taught authentication the hard way — hashing, sessions, tokens, rotation — because you needed to understand the machinery. Here's the reward: Supabase runs that exact machinery for you, and — this is the part most tutorials skip — it runs it *inside the same database*, which is what lets a SQL policy ask 'who is asking?' at all. This lesson connects identity to your data, then shows Storage and Realtime obeying the same rules." },
    { t: "why", text: ["**Why not roll your own here?** You could — Volume IV proved you can. But auth is the one subsystem where a subtle bug is a breach, the requirements keep growing (OAuth providers, MFA, email verification, session revocation), and the correct implementation is boring and identical across apps. Borrowing a battle-tested one is engineering judgment, not laziness. What you must still own: the *authorization* model — which is precisely RLS, the next module.", "**Why does auth.uid() matter so much?** Because it is the single point where 'a JWT in an HTTP header' becomes 'a user id inside a SQL query'. Every policy, every storage rule, every realtime filter hangs off it. Understand that hinge and the three services stop feeling like separate products."], },
    { t: "simple", text: ["Auth is the **front desk that issues ID badges**. It keeps its own guestbook (auth.users), hands out badges that expire (sessions), and can vouch for people via other front desks (OAuth). When you walk into any room — the tasks table, a storage bucket, a realtime channel — the room's rules ask one question of your badge: *whose name is on it?* That answer is auth.uid()."], },
    { t: "model", title: "One identity, three rooms", text: [
      "**Auth owns identity.** signUp/signIn produce a session: an access token (short-lived JWT, carries the user id) and a refresh token (longer-lived, rotates on use — Volume IV's rotation discipline, managed for you). The users live in auth.users; YOUR domain never stores passwords, hashes, or verification flags.",
      "**Your schema connects via profiles.** The canonical pattern: a public.profiles table with id bigint references auth.users, created by a trigger on signup. Now every domain table can hang user_id off profiles — and policies compare user_id = auth.uid() without ever touching the auth schema directly.",
      "**Storage and Realtime are rooms, not products.** A storage bucket is a table of objects guarded by storage.policies — same policy language, same auth.uid(). A realtime channel delivers row changes only if the subscriber's role can already SELECT that row under RLS. One identity, one policy language, three doors.",
    ], map: [
      ["The front desk and its guestbook", "Auth: users table + sessions; you never store credentials"],
      ["The badge with a name on it", "auth.uid() — the id policies compare against"],
      ["A coat check with per-hook rules", "Storage buckets: objects guarded by policies"],
      ["A news feed that checks your clearance per story", "Realtime: row changes filtered by the same RLS"],
    ] },
    { t: "code", lang: "sql", title: "The profiles pattern: identity meets your schema", code: "-- profiles mirrors the people you care about, in YOUR schema:\ncreate table public.profiles (\n  id bigint primary key references auth.users on delete cascade,\n  handle text not null unique,\n  created_at timestamptz not null default now()\n);\n\n-- Born automatically when someone signs up:\ncreate function public.handle_new_user()\nreturns trigger language plpgsql security definer set search_path = public as $$\nbegin\n  insert into public.profiles (id, handle)\n  values (new.id, 'user_' || left(new.id::text, 8));\n  return new;\nend $$;\n\ncreate trigger on_auth_user_created\n  after insert on auth.users\n  for each row execute function public.handle_new_user();\n\n-- And domain tables point at profiles, not auth:\ncreate table public.tasks (\n  id bigint generated always as identity primary key,\n  user_id bigint not null references public.profiles(id),\n  title text not null,\n  done boolean not null default false\n);\nalter table public.tasks enable row level security; -- policies next module", notes: ["security definer lets the trigger write to profiles even before RLS policies exist for the new user — but it also means the function runs with elevated rights, so its body must be tiny and reviewed. search_path is pinned so nothing hijacks name resolution.", "on delete cascade here is deliberate: when Auth deletes the user, their profile and (via its own FKs) their data go with them. 'What happens to their rows' is answered in the schema, per Volume V."], },
    { t: "code", lang: "js", title: "Sessions, sign-in choices, and the state they produce", code: "// Email + password:\nawait supabase.auth.signUp({ email, password });\n\n// Magic link — no password to store, leak, or forget:\nawait supabase.auth.signInWithOtp({ email });\n\n// OAuth — identity vouched by another provider:\nawait supabase.auth.signInWithOAuth({ provider: \"github\" });\n\n// The session is the artifact everything else uses:\nconst { data: { session } } = await supabase.auth.getSession();\n// session.access_token  → JWT, expires ~1h, carries the user id\n// session.refresh_token → rotates on refresh (reuse = theft alarm,\n//                          exactly as Volume IV described)\n\n// React apps subscribe instead of polling:\nsupabase.auth.onAuthStateChange((_event, session) => {\n  // session null = signed out; otherwise the badge is live\n});", notes: ["Choose the sign-in method by your threat model and UX: passwords need strength + breach checks you'd otherwise hand-roll; magic links trade a password for email access; OAuth trades both for provider trust. All three end in the same session object — the database can't tell, and doesn't need to.", "Never cache 'am I logged in' beyond the session's lifetime; onAuthStateChange and getSession are the sources of truth, including token refreshes you never see."], },
    { t: "code", lang: "js", title: "Storage and Realtime: same badge, same rules", code: "// STORAGE — upload through the authorized path; policies (next\n// module) decide who may write where and who may read what.\nawait supabase.storage\n  .from(\"avatars\")\n  .upload(`${user.id}/avatar.png`, file, { upsert: true });\n\nconst { data } = supabase.storage.from(\"avatars\").getPublicUrl(`${user.id}/avatar.png`);\n\n// REALTIME — subscribe to changes on rows YOU may already read:\nsupabase\n  .channel(\"my-tasks\")\n  .on(\"postgres_changes\",\n      { event: \"*\", schema: \"public\", table: \"tasks\", filter: `user_id=eq.${user.id}` },\n      (payload) => { /* payload.new / payload.old / payload.eventType */ })\n  .subscribe();\n\n// The authorization question — 'may this subscriber see this\n// row?' — is answered by the SAME RLS policies that guard SELECT.\n// Enable per table: alter publication supabase_realtime add table public.tasks;", notes: ["Storage paths are your folder policy: scoping uploads under ${user.id}/ means the policy 'users write only under their own folder' is a one-liner — and enforceable, unlike a client-side convention.", "Realtime is not a bypass around RLS; it is RLS with a subscription attached. If a user can't SELECT a row, they never see its change event."], },
    { t: "debug", title: "Debugging lab — 'profiles exists for me but not for my teammate'", scenario: "You sign up: your profile appears, tasks work. Your teammate signs up: their insert into tasks fails with a foreign-key violation on user_id. The trigger is 'obviously' deployed — you saw it run for you.", error: "-- The trigger was created in the dashboard SQL editor…\n-- …while logged into the local project.\n-- Production never received it.\n\n-- Meanwhile, local signups worked, so every test passed.\n-- The error surfaces only as:\n--   insert or update on table \"tasks\" violates foreign key\n--   constraint \"tasks_user_id_fkey\"", tells: "A foreign-key violation on a trigger-maintained column means the parent row never existed — and when 'it works for me but not for new users', the usual cause is infrastructure that lives outside Git: a dashboard-created trigger, a policy applied by hand, a function that exists in one environment only. The schema has history; the dashboard has amnesia.", flow: ["Read the error — tasks_user_id_fkey says profiles.id is missing for this user. So handle_new_user never fired for them.", "Identify the layer — schema drift between environments, not application code.", "Reproduce — on a fresh environment, sign up and query profiles; empty. Locally: populated.", "Hypothesize — compare pg_trigger across environments: the trigger (or its function) is absent where signup fails.", "Change one variable — move the function + trigger into a MIGRATION FILE, supabase db push, sign up again in the affected environment.", "Verify — new users get profiles everywhere; and the migration file means no environment can drift again."], root: "Schema objects created by hand exist only where the hand was. The fix is not re-clicking in the dashboard — it is making the schema fully reproducible from files, so every environment converges by construction.", prevent: "Rule: if it isn't in supabase/migrations, it doesn't exist. CI applies migrations to a fresh database on every push — drift becomes a failed build instead of a teammate-shaped mystery." },
    { t: "mistake", title: "Storing your own passwords 'for later migration'", wrong: "Adding password_hash to profiles because 'Supabase Auth might not be enough' — creating a second credential store nobody audits.", right: "Auth is the credential owner; profiles holds domain facts. If you need MFA or SAML, configure Auth — don't fork it. Two password stores means two breach surfaces and one of them untested.", explain: "Every credential store you own is a liability you staff. The profiles pattern exists precisely to give you identity-linked data without ever touching the secret parts." },
    { t: "note", kind: "security", title: "The refresh token is the crown jewel on the client", text: ["Access tokens die in an hour by design; the refresh token is what makes 'stay signed in' work — which makes it the thing attackers want. supabase-js stores it as configured (local storage by default in browsers); sensitive apps tighten this: short sessions, detect_reused_token enabled (a reused refresh token revokes the whole family — the theft alarm from Volume IV, enforced for you), and sign-out on privilege changes."], },
    { t: "try", title: "Try it yourself", steps: ["In your local project, sign up two users via Studio's Auth page; then query auth.users and public.profiles in the SQL editor. Map every column you see to a Volume IV concept (hashing, verification, sessions).", "Write and apply the handle_new_user migration from this lesson; sign up a third user and watch the trigger create their profile without any client code.", "Upload an avatar under ${user.id}/ for both users. Predict — before writing any policy — what the other user can currently do with that URL, and verify your prediction.", "Stretch: subscribe to postgres_changes on tasks for user A, then update a row as user B. Explain exactly why A sees nothing — name the layer that decided."], },
    { t: "quiz", title: "Check your understanding", questions: [
      { id: "q1", type: "single", prompt: "In the profiles pattern, your domain tables' user_id should reference…", options: ["auth.users directly from every table", "public.profiles(id), which itself references auth.users", "a copy of the user's email", "the JWT's raw string"], answer: [1], explain: "One bridge table keeps your schema decoupled from the auth schema: domain tables point at profiles, profiles points at auth.users, and cascade deletion flows correctly. Emails are mutable facts, not identities.", tags: ["supabase-auth-storage"] },
      { id: "q2", type: "single", prompt: "The access token and refresh token split exists because…", options: ["JWTs cannot be revoked, so short access lifetimes plus a rotatable, revocable refresh token reconcile statelessness with control", "refresh tokens are encrypted and access tokens aren't", "browsers can only store one token", "it's a Supabase-specific quirk"], answer: [0], explain: "Exactly the Volume IV trade-off, managed for you: stateless access tokens (cheap to verify everywhere, impossible to revoke) paired with server-held refresh tokens (revocable, rotating, reuse-detected).", tags: ["supabase-auth-storage", "sessions-tokens"] },
      { id: "q3", type: "boolean", prompt: "A Realtime subscriber receives change events for rows their RLS policies would not let them SELECT.", options: ["True", "False"], answer: [1], explain: "False — realtime authorization IS the RLS check with a subscription attached. No SELECT right, no change events. Realtime extends the boundary; it never punches through it.", tags: ["supabase-auth-storage", "rls-first-principles"] },
      { id: "q4", type: "single", prompt: "Storage uploads are scoped to ${user.id}/avatar.png primarily so that…", options: ["filenames stay unique", "a bucket policy can enforce 'write only under your own folder' as a rule the database checks, not a client convention", "CDNs require it", "it compresses better"], answer: [1], explain: "The path convention becomes enforceable: the policy checks (storage.foldername(name))[1] = auth.uid()::text. Conventions in client code are suggestions; this one is a law.", tags: ["supabase-auth-storage", "rls-first-principles"] },
      { id: "q5", type: "single", prompt: "A teammate's signup produces no profile row; yours worked. The first suspicion is…", options: ["their browser blocked the trigger", "schema drift — the trigger or function exists in your environment but was never deployed as a migration", "their email is unverified", "profiles has a UNIQUE conflict"], answer: [1], explain: "'Works for me, fails for every new user' on trigger-maintained data is the signature of dashboard-only schema objects. The FK error is downstream; the missing trigger is upstream.", tags: ["supabase-auth-storage"] },
      { id: "q6", type: "multi", prompt: "Select ALL things Supabase Auth owns, so your schema never has to.", options: ["Password hashing and verification", "Email verification and magic links", "Session issuance and refresh rotation", "Which of your tables a user may read"], answer: [0, 1, 2], explain: "Credentials, verification, and sessions are Auth's job. Authorization over YOUR tables is your job — expressed as RLS policies, the next module. Confusing these two is how apps either rebuild Auth badly or skip authorization entirely.", tags: ["supabase-auth-storage", "auth-models"] },
    ] },
    { t: "vocab", terms: [["auth.users", "The schema-owned table of identities; credentials and verification live here, never in your schema."], ["auth.uid()", "The function that resolves the current JWT to a user id inside SQL — the hinge of the whole security model."], ["Profiles pattern", "A public.profiles bridge table (id → auth.users) that domain tables reference."], ["Session", "Access token (short-lived JWT) plus refresh token (rotating, revocable)."], ["Storage policy", "RLS-language rules over buckets: who uploads where, who reads what."], ["Realtime authorization", "Change events delivered only for rows the subscriber may SELECT under RLS."]] },
    { t: "recap", items: ["Auth is the front desk: users table, sessions, OAuth — you never store credentials.", "auth.uid() is the hinge: JWT in, user id out, inside SQL.", "Profiles bridge identity to domain data; FKs and cascade answer 'what happens to their rows'.", "Storage and Realtime obey the same policy language and the same identity — rooms, not products.", "Triggers and functions live in migrations; dashboard objects are environment-local amnesia."] },
    { t: "checkpoint", text: "Draw the chain from signup to a tasks insert: which table, which trigger, which foreign keys, which token. Then state what Storage and Realtime share with your tables. Both from memory? Mark complete." },
    { t: "bridge", text: "Identity is issued and connected — but right now, the rooms have no rules, and the master-key problem from lesson one is still one bad policy away. Next module: Row Level Security from first principles — the house rules themselves.", next: "rls-first-principles" },
  ],
};

const rlsFirstPrinciples: Lesson = {
  id: "rls-first-principles",
  title: "Row Level Security: The House Rules, Written in SQL",
  volume: 6, module: 2, order: 1, level: "Full-Stack", status: "implemented", minutes: 60,
  summary: "RLS is authorization enforced by the database on every query from every client: no policy means deny, policies OR together, USING guards reads and WITH CHECK guards writes. This lesson builds the complete policy vocabulary and the patterns that make 'user A never sees user B' a law instead of a hope.",
  prereqs: ["supabase-auth-storage"],
  objectives: [
    "State the default posture: RLS enabled + no policy = total denial, and why that default is the point",
    "Write policies with USING (reads) and WITH CHECK (writes), and explain what each guards",
    "Predict how multiple policies combine (OR within an operation) and why order never matters",
    "Apply the owner pattern, the public-read/private-write pattern, and the admin-via-table pattern",
    "Avoid the three classic holes: missing WITH CHECK, anon overreach, and the 'disable RLS to make it work' trap",
  ],
  concepts: ["RLS", "policy", "USING", "WITH CHECK", "auth.uid()", "force row level security", "security definer"],
  blocks: [
    { t: "lead", text: "Here is the sentence the rest of the course keeps cashing in: **Row Level Security means the database itself refuses to show a user rows they may not see — no matter what the client asks, no matter which API path, no matter how clever the request.** Everything before this lesson was plumbing for this moment: roles provide the identity, policies provide the rules, and the query planner glues them into every statement before a single row leaves the building." },
    { t: "why", text: ["**Why enforce in the database and not in the API?** Because the API is one caller. The mobile app, the admin tool, the realtime subscription, the partner integration, the bug in next quarter's feature — all of them reach the same tables, and each one would need its own perfect copy of your authorization logic. RLS puts the logic where the data lives: written once, enforced everywhere, impossible to route around from inside the system. Volume IV said 'the server is the only gate you can't walk around' — RLS is the same idea one layer deeper: the *database* is the gate the server can't walk around.", "**Why is the default deny?** Because 'allowed unless forbidden' means every new table is public until someone remembers to lock it — and someone won't, at 2 a.m., during a launch. 'Forbidden unless allowed' inverts the failure mode: a forgotten policy makes a feature broken (visible, testable, fixable) instead of making your data public (invisible, silent, catastrophic)."], },
    { t: "simple", text: ["Every table gets a **bouncer with a clipboard**. The clipboard lists who may come in (read) and who may put things down or take things away (write). No name on the clipboard? No entry — that's the default. Multiple entries for the same door? If ANY of them says yes, you're in. And the owner of the building? By an old law, they walk past the bouncer entirely — unless you explicitly post a sign saying the rules apply to them too. That sign is force row level security, and forgetting it is the most expensive one-line omission in this volume."], },
    { t: "model", title: "USING guards the door in; WITH CHECK guards the door out", text: [
      "A policy is a named rule attached to (table, operation, role). Its two clauses answer two different questions. **USING (expr)** — 'may this existing row be seen/touched?' — evaluated against rows already in the table, for SELECT, and as the filter on UPDATE/DELETE targets. **WITH CHECK (expr)** — 'may this new row exist?' — evaluated against the row about to be written, for INSERT and UPDATE results.",
      "Three composition rules, all of them good news once internalized: policies for the same operation are **ORed** (any yes wins — you grant access by adding rules, never by editing a giant condition); there is **no deny keyword** (you restrict by simply not granting); and policies are **declarative** — no order, no short-circuit, the planner folds them into the query.",
      "And the three doors: **SELECT** policies decide reads, **INSERT/UPDATE/DELETE** policies decide writes, and **ALL** is shorthand when the rule is identical. A table with only a SELECT policy is read-only to that role — the writes are denied by absence, which is exactly the design.",
    ], map: [
      ["The bouncer's clipboard", "Policies: named rules per table and operation"],
      ["'On the list?' at the door", "USING — may this existing row be touched"],
      ["'Does this belong here?' on the way in with a box", "WITH CHECK — may this new row exist"],
      ["Any yes on the clipboard wins", "Policies OR together; absence is the only no"],
      ["The owner's 'rules apply to me too' sign", "force row level security on the table owner"],
    ] },
    { t: "code", lang: "sql", title: "The owner pattern — the policy you will write a hundred times", code: "alter table public.tasks enable row level security;\n\n-- READ your own rows:\ncreate policy \"tasks_select_own\" on public.tasks\n  for select using (user_id = auth.uid());\n\n-- CREATE rows that belong to you:\ncreate policy \"tasks_insert_own\" on public.tasks\n  for insert with check (user_id = auth.uid());\n\n-- UPDATE rows you own — and the result must still be yours:\ncreate policy \"tasks_update_own\" on public.tasks\n  for update\n  using      (user_id = auth.uid())   -- may touch only your rows\n  with check (user_id = auth.uid());  -- may not reassign them away\n\n-- DELETE rows you own:\ncreate policy \"tasks_delete_own\" on public.tasks\n  for delete using (user_id = auth.uid());\n\n-- The hinge, again: auth.uid() is the current JWT's user id,\n-- evaluated by the database, inside every query, for every client.", notes: ["Notice the UPDATE policy carries BOTH clauses: USING picks which rows you may target; WITH CHECK stops you from updating user_id to someone else's id. Omit the second and 'edit your task' quietly becomes 'donate your task to a stranger'.", "For roles other than the table owner (anon, authenticated), RLS applies automatically. For the OWNER (often postgres), add: alter table public.tasks force row level security; — otherwise the owner sails past every bouncer."], },
    { t: "code", lang: "sql", title: "Two more patterns you will recognize everywhere", code: "-- PUBLIC READ, PRIVATE WRITE — content sites, catalogs, docs:\ncreate policy \"posts_read_all\" on public.posts\n  for select using (true);            -- anyone, even anon\ncreate policy \"posts_write_authors\" on public.posts\n  for insert with check (author_id = auth.uid());\n-- No update/delete policies exist: authors can post, nobody\n-- (except privileged roles) can edit or remove. Absence = no.\n\n-- ADMIN VIA A TABLE, not via a flag in your code:\ncreate table public.admins (\n  user_id bigint primary key references public.profiles(id)\n);\ncreate policy \"tasks_admin_all\" on public.tasks\n  for all\n  using      (exists (select 1 from public.admins a\n                      where a.user_id = auth.uid()))\n  with check (exists (select 1 from public.admins a\n                      where a.user_id = auth.uid()));\n-- Granting admin = an INSERT into admins. The policy checks\n-- the table, live, on every query. No code deploy required.", notes: ["Admin-as-table keeps authorization in the database: rotating an admin is one row, auditable in the same schema as everything else. A boolean is_admin on profiles works too — but it lives one UPDATE away from any write path that touches profiles, whereas a dedicated table narrows the blast radius.", "exists (select 1 …) is the idiomatic membership test — cheap, index-friendly on the primary key, and readable as English: 'there exists an admin row for the current user'."], },
    { t: "debug", title: "Debugging lab — 'users can edit anyone's task'", scenario: "QA reports that a logged-in user can change the owner of somebody else's task — the UI even re-renders it under the new owner. All four policies exist. The bug is not a missing policy; it is a missing clause.", error: "create policy \"tasks_update_own\" on public.tasks\n  for update\n  using (user_id = auth.uid());\n  -- WITH CHECK: (missing)\n\n-- The attack, from any client:\nupdate tasks set user_id = <victim> where id = <their task>;\n-- USING passes? No — you don't own the target row…\n-- …but via the API, the client issues the update against rows\n-- it owns: update tasks set user_id = <victim> where id = <own task>;\n-- USING: user_id = auth.uid() ✔ (it's your row)\n-- WITH CHECK: none → the rewritten row sails through.\n-- You just mailed your task to a stranger.", tells: "The signature of a missing WITH CHECK is a write that starts legal and ends illegal: the target row passes USING, but the resulting row violates a rule no clause checks. Whenever 'users can X' reports involve changed ownership, status escalation, or quota fields, read the UPDATE and INSERT policies for their WITH CHECK line before anything else.", flow: ["Read the policies — enumerate clauses per operation: USING present, WITH CHECK absent on update.", "Identify the layer — write-path authorization; reads are irrelevant to this bug.", "Reproduce — as user A, PATCH your own task with user_id set to user B's id. It succeeds. That's the exploit, in one request.", "Hypothesize — add with check (user_id = auth.uid()); the result row must still be yours.", "Change one variable — recreate the policy with both clauses; repeat the PATCH.", "Verify — the reassignment now fails with a row-level security violation; legitimate edits still pass."], root: "USING filters which rows you may aim at; WITH CHECK validates what the row becomes. An UPDATE policy with only USING authorizes the trigger pull but not the bullet's destination. Every write policy needs both questions answered.", prevent: "Checklist for every write policy: does USING restrict targets, and does WITH CHECK restrict outcomes? Code-review rule: an UPDATE policy that can change the authorization-relevant column (user_id, status, role) without a WITH CHECK is rejected." },
    { t: "mistake", title: "'Disable RLS to make it work'", wrong: "alter table tasks disable row level security; because the policy 'wasn't working' — converting a configuration problem into a public table.", right: "A denial is a diagnosis, not an obstacle: check the role making the call, the operation, the policy's expression (test it as a WHERE clause in the SQL editor), and whether the table owner needs force row level security. Then fix the rule.", explain: "Every 'disable RLS' commit is a decision to make the table public to every holder of the publishable key — permanently, silently, until someone notices. The debugging loop is short and mechanical; the incident it prevents is not." },
    { t: "outdated", lang: "js", label: "The pre-RLS era: authorization as a WHERE clause in app code", oldCode: "// 2015 BaaS pattern — every query hand-filtered:\nconst rows = await db\n  .from('tasks')\n  .select('*')\n  .eq('user_id', currentUser.id);  // trust the client to ask nicely\n\n// Every screen, endpoint, and cron repeated the filter.\n// Miss it once — a new dashboard, an admin view, an export —\n// and the table is public to anyone logged in.", now: "Policies in the database; the client just asks", nowCode: "alter table tasks enable row level security;\ncreate policy \"own\" on tasks\n  for all using (user_id = auth.uid())\n  with check (user_id = auth.uid());\n\n// The client:\nconst rows = await supabase.from('tasks').select('*');\n// The filter is appended by the database, on every path,\n// forever. New features inherit safety instead of re-implementing it.", why: "Client-side filtering authorizes the happy path and forgets the other eleven paths. RLS makes the authorization a property of the data rather than a habit of the callers — which is the only kind of security that survives the next deadline." },
    { t: "note", kind: "security", title: "security definer is a loaded gun with a safety", text: ["Functions marked security definer run as their OWNER (often postgres), bypassing the caller's limits — necessary for triggers like handle_new_user, and exactly as dangerous as it sounds. Rules: keep the body minimal, pin search_path (set search_path = public), never accept unvalidated table/column names, and review every definer function like you review password code. A definer function with a hole is a policy bypass with a function's name on it."], },
    { t: "note", kind: "performance", title: "Policies are WHERE clauses — index them", text: ["RLS appends your policy expressions to every query on the table, so a policy on user_id = auth.uid() means every select filters by user_id — which means user_id wants an index (Volume V's rule: foreign keys don't index themselves). EXPLAIN ANALYZE a query as the authenticated role (set role authenticated; set request.jwt.claims …) and you'll see the policy folded into the plan like any other predicate. Policies don't add a separate cost layer; they add predicates you must plan for."], },
    { t: "try", title: "Try it yourself", steps: ["On your local project, enable RLS on tasks with NO policies and query as the anon and authenticated roles. Confirm total denial — then add only the SELECT-own policy and confirm reads work while every write is refused. Feel the default-deny posture.", "Write all four owner policies for tasks, then attempt the ownership-donation attack from the debugging lab against your own row. Confirm WITH CHECK stops it.", "Implement public-read/private-write on a posts table and the admins-table admin pattern. As a non-admin, confirm you can read everything, write your own, and touch nothing else.", "Stretch: run set role authenticated; plus a hand-set JWT claims block in the SQL editor and EXPLAIN ANALYZE a select — find the RLS predicate in the plan and the index (or seq scan) it uses."], },
    { t: "quiz", title: "Check your understanding", questions: [
      { id: "q1", type: "single", prompt: "A table has RLS enabled and zero policies. A logged-in user queries it. What happens?", options: ["all rows return — policies only restrict", "an error naming the missing policy", "zero rows — enabled RLS with no matching policy denies everything", "only the user's rows, by convention"], answer: [2], explain: "Enabled + no policy = deny. The failure mode is a broken feature (loud, testable), never a public table (silent, catastrophic). That inversion is the entire design philosophy.", tags: ["rls-first-principles"] },
      { id: "q2", type: "single", prompt: "USING and WITH CHECK guard, respectively…", options: ["reads; writes", "which existing rows may be touched; whether the resulting/new row may exist", "the anon role; the authenticated role", "SELECT; ALL"], answer: [1], explain: "USING evaluates rows already in the table (what you may see/target); WITH CHECK evaluates the row being written (what may come to exist). UPDATE needs both: target legal, outcome legal.", tags: ["rls-first-principles"] },
      { id: "q3", type: "single", prompt: "Two SELECT policies exist on a table: one for owners, one for team members. A row matches the team policy but not the owner policy. Access is…", options: ["denied — both must pass", "granted — policies OR together within an operation", "granted only if the owner policy comes first", "undefined — conflicting policies error"], answer: [1], explain: "Any yes wins. You build access by adding policies; you never edit one giant condition, and order is irrelevant — the planner folds them all into the query.", tags: ["rls-first-principles"] },
      { id: "q4", type: "single", prompt: "The table OWNER (e.g. postgres) is exempt from RLS unless you…", options: ["grant them the authenticated role", "add alter table … force row level security", "write an owner-deny policy", "restart the database"], answer: [1], explain: "PostgreSQL historically lets owners bypass RLS. force row level security posts the 'rules apply to me too' sign. Forgetting it while connecting as the owner is the classic 'RLS works in tests but not in prod' inversion.", tags: ["rls-first-principles"] },
      { id: "q5", type: "single", prompt: "An UPDATE policy has only using (user_id = auth.uid()). The concrete exploit is…", options: ["reading other users' rows", "updating your own row to set user_id to a victim's id — reassigning it away", "deleting the table", "impersonating the service role"], answer: [1], explain: "USING let you aim at your own row; with no WITH CHECK, the rewritten row — now owned by someone else — passes unchallenged. Every write policy that can alter the authorization column needs both clauses.", tags: ["rls-first-principles"] },
      { id: "q6", type: "multi", prompt: "Select ALL correct statements about modeling admins with RLS.", options: ["An admins table checked via exists(…) keeps the grant in the database, auditable and deploy-free", "A security definer function should pin search_path and keep a minimal body", "Storing is_admin on profiles is equally safe because profiles is protected", "Disabling RLS for admin sessions is the cleanest approach"], answer: [0, 1], explain: "Membership-as-table and disciplined definer functions are the professional patterns. is_admin on profiles puts the flag one careless UPDATE policy away from mass privilege escalation, and 'disable RLS for admins' removes every rule for every query in that session — admins get a policy (the ALL + exists pattern), not an exemption.", tags: ["rls-first-principles"] },
    ] },
    { t: "vocab", terms: [["Row Level Security", "Per-table, per-operation rules the database folds into every query — authorization as a property of the data."], ["Policy", "A named (table, operation, role) rule with USING and/or WITH CHECK expressions."], ["USING", "Guard over existing rows: what may be seen or targeted."], ["WITH CHECK", "Guard over written rows: what may come to exist."], ["Default deny", "Enabled RLS + no matching policy = no rows. Forgotten rules break features, not confidentiality."], ["force row level security", "Makes RLS apply to the table's owner too."], ["security definer", "A function that runs as its owner — elevated power requiring pinned search_path and minimal bodies."]] },
    { t: "recap", items: ["RLS = the database refusing unauthorized rows on every path; enabled + no policy = deny.", "USING guards what you may touch; WITH CHECK guards what may be written; updates need both.", "Policies OR within an operation; absence is the only denial; order is meaningless.", "Owner patterns, public-read/private-write, and admin-via-table cover the daily shapes.", "force row level security for owners; definer functions treated as loaded guns; policies are predicates you index."] },
    { t: "checkpoint", text: "Write the four owner policies for tasks from memory, then state — without looking — what a table with RLS enabled and zero policies returns to a logged-in user, and why that default was chosen. Clean on both? Mark complete." },
    { t: "bridge", text: "The house rules are written — but rules nobody tests are wishes. The final lesson of this volume turns RLS into a tested contract: the user-A-vs-user-B matrix, service-role discipline, storage and realtime policies, and the catalog of policy bugs that ships to production when the matrix is skipped.", next: "rls-testing-discipline" },
  ],
};

const rlsTestingDiscipline: Lesson = {
  id: "rls-testing-discipline",
  title: "Testing RLS: The Matrix That Makes Policies a Contract",
  volume: 6, module: 2, order: 2, level: "Full-Stack", status: "implemented", minutes: 55,
  summary: "A policy you haven't attacked is a policy you've only half-written. This lesson builds the user-A-vs-user-B test matrix, the role-escalation checks, storage and realtime policies, and the debugging loop for the denials and over-grants that actually ship.",
  prereqs: ["rls-first-principles"],
  objectives: [
    "Write the four-cell authorization matrix (A reads B, A writes B, anon reads, anon writes) for every table",
    "Run policy tests as real roles locally — JWT claims for users, service role for admin paths",
    "Author storage policies scoped to user folders and realtime-safe table settings",
    "Diagnose both failure classes: over-grant (silent) and over-denial (loud), with the SQL-editor loop",
    "Treat service-role usage as audited server code — never a workaround for a failing policy",
  ],
  concepts: ["authorization matrix", "role impersonation", "storage policies", "realtime policies", "over-grant", "over-denial"],
  blocks: [
    { t: "lead", text: "Volume IV's security lesson ended on a testing rule: never trust that a user can't reach another user's data — prove it, as both users, in CI. Row Level Security makes that proof executable: because the database enforces the rules, the test is simply 'act as A, try B's data, expect refusal'. This lesson turns that sentence into a matrix you run against every table — because policies have two failure classes, and only one of them is loud." },
    { t: "why", text: ["**Why must RLS be tested like an API contract?** Because its failure modes are asymmetric. An over-DENIAL breaks a feature: a button stops working, a screen shows empty, someone files a ticket — the system announces its own bug. An over-GRANT breaks nothing visible: the wrong rows simply appear, quietly, for anyone who asks the right question — and 'asks the right question' is precisely what attackers do. The silent class is why authorization is tested adversarially or not at all.", "**Why not test through the UI?** The UI only exercises the paths you built. The API accepts any well-formed request: handcrafted filters, other users' ids, write verbs your buttons never send. Testing at the client/SQL level attacks the actual surface — the database — the same surface an attacker reaches."], },
    { t: "simple", text: ["Think of the matrix as a **fire-drill grid for every door**. For each room (table), you send four inspectors: Can resident A get into resident B's room? Can A move B's furniture? Can a stranger off the street look in? Can the stranger move anything? Any 'yes' where the answer should be 'no' gets fixed before opening day — and the drill runs automatically every single week (CI), because doors have a way of being left open by whoever renovates next."], },
    { t: "model", title: "The four cells, plus the two keys you test with", text: [
      "**The matrix.** Every table gets the same four questions, answered by executable tests: (1) user A reads user B's rows → must be denied; (2) user A writes/updates/deletes user B's rows → denied; (3) anon (not logged in) reads → denied unless the table is intentionally public; (4) anon writes → denied. Owners reading and writing their OWN rows are the positive controls — if those fail, you've over-denied and broken the feature.",
      "**The impersonation.** Locally, you test as real roles: create two users in Studio, sign in as each, run the matrix with that user's session (auth.uid() resolves to them). For admin paths, run with the service-role client from a SERVER context — and treat every such call as audited, because in production it bypasses everything you just tested.",
      "**The two failure classes, again, as a discipline.** Over-grant: silent — hunt for it with the matrix. Over-denial: loud — hunt for it with the positive controls and the policy-debug loop (read the policy as a WHERE clause, evaluate it by hand in the SQL editor, check the role, check force row level security, check that the policy even exists in this environment — migrations, remember).",
    ], map: [
      ["The fire-drill grid", "The four-cell matrix, run per table, in CI"],
      ["Sending the inspector in with B's badge", "Impersonation: test as real roles, not as the app"],
      ["The silent open door", "Over-grant — only the matrix finds it"],
      ["The jammed locked door", "Over-denial — loud; debug the policy, never disable it"],
    ] },
    { t: "code", lang: "ts", title: "The matrix, as a test suite you will copy forever", code: "// vitest + two local users (ada, grace) created in Studio.\ndescribe(\"tasks RLS matrix\", () => {\n  // Clients hold real sessions — auth.uid() is real in the DB.\n  const ada = await clientFor(ADA_EMAIL);    // signInWithPassword\n  const grace = await clientFor(GRACE_EMAIL);\n  const graceTask = await createTaskAs(grace, \"grace's secret\");\n\n  it(\"A cannot READ B's rows\", async () => {\n    const { data } = await ada.from(\"tasks\").select(\"*\").eq(\"id\", graceTask.id);\n    expect(data).toHaveLength(0);            // denied = invisible\n  });\n\n  it(\"A cannot WRITE B's rows\", async () => {\n    const { data, error } = await ada.from(\"tasks\")\n      .update({ done: true }).eq(\"id\", graceTask.id).select();\n    expect(data).toHaveLength(0);             // nothing updated\n  });\n\n  it(\"anon cannot read\", async () => {\n    const { data } = await anonClient.from(\"tasks\").select(\"*\");\n    expect(data).toHaveLength(0);\n  });\n\n  it(\"POSITIVE CONTROL: owner reads own row\", async () => {\n    const { data } = await grace.from(\"tasks\").select(\"*\").eq(\"id\", graceTask.id);\n    expect(data).toHaveLength(1);\n  });\n});\n// The first three cells hunt the silent class.\n// The fourth proves the door isn't jammed.", notes: ["Denied reads return empty, not an error — PostgREST filters rather than refusing, which is why expect(0) is the assertion and why over-grants are invisible to error monitoring.", "The update cell asserts on the RETURNED rows (.select() after update): zero rows means the USING clause rejected the target. Without .select() you'd be asserting on a count the API reports as 0 anyway — test the data, not the status code."], },
    { t: "code", lang: "sql", title: "Storage and realtime: the same rules, other doors", code: "-- STORAGE: avatars bucket — write under your own folder, read anyone's:\ninsert into storage.buckets (id, name, public) values ('avatars','avatars', true);\n\ncreate policy \"avatars_write_own\" on storage.objects\n  for insert to authenticated\n  with check (\n    bucket_id = 'avatars'\n    and (storage.foldername(name))[1] = auth.uid()::text\n  );\ncreate policy \"avatars_read_all\" on storage.objects\n  for select using (bucket_id = 'avatars');\n-- (plus an update/delete policy scoped the same way as write)\n\n-- REALTIME: opt the table in, and remember the authorization\n-- model is still RLS — subscribers only receive rows they can SELECT:\nalter publication supabase_realtime add table public.tasks;\n\n-- The DEBUG LOOP for any denial, straight in the SQL editor:\nset role authenticated;\nselect auth.uid();                -- who am I in this session?\nselect * from tasks where id = 7; -- does the policy-folded query see it?\nselect * from tasks;              -- what does my role see at all?\n-- Read each policy's expression as a plain WHERE clause\n-- against the row in question. The mismatch is always visible.", notes: ["foldername(name))[1] is the path-convention-as-law from the previous lesson: uploads outside ${user.id}/ are refused by the database, whatever the client intended.", "set role authenticated in the SQL editor is the fastest policy debugger: you become the role, auth.uid() resolves (with a claims block if needed), and you read exactly what the client reads — minus the network, minus the client, minus the excuses."], },
    { t: "debug", title: "Debugging lab — 'my own tasks vanished'", scenario: "After a teammate 'cleaned up' the policies, logged-in users see an empty task list. Nothing errors. The app is healthy; the data exists; the screen is blank. Somewhere between the last working commit and now, a door that should open now won't.", error: "-- The cleanup diff:\n- create policy \"tasks_select_own\" on public.tasks\n-   for select using (user_id = auth.uid());\n+ create policy \"tasks_select_own\" on public.tasks\n+   for select to authenticated\n+   using (user_id = auth.uid()::text);   -- 'just being explicit'\n\n-- user_id is bigint. auth.uid() is uuid.\n-- bigint = uuid::text is never true.\n-- Every select now matches zero rows — for everyone.", tells: "A sudden app-wide empty list with no errors is the over-denial signature: RLS filtered everything out. When it follows a policy diff, the diff is the crime scene — and type mismatches in policy expressions are the classic silent killer, because = between mismatched types simply evaluates to false (or errors, depending on the cast) rather than announcing itself.", flow: ["Read the symptom — empty list for all users, zero errors. Denial, not crash: think policy.", "Identify the layer — authorization, not network or state. Confirm data exists via the SQL editor as postgres (bypasses RLS): it does.", "Reproduce — set role authenticated; select * from tasks; → zero rows, as the client sees.", "Hypothesize — diff the policies against the last working migration; spot the ::text cast on the uuid.", "Change one variable — remove the cast (or compare user_id = auth.uid() with matching types); re-run the role query.", "Verify — rows return; then run the whole matrix suite, because a 'cleanup' that broke one clause may have touched others."], root: "Policy expressions are ordinary SQL — including ordinary type bugs — but their failures surface as authorization outcomes, not exceptions. A wrong expression doesn't raise; it denies.", prevent: "Policies live in migrations (the diff is reviewable), the matrix suite runs in CI (the denial is caught before deploy), and the SQL-editor role loop is the first diagnostic, not the last resort." },
    { t: "mistake", title: "The service role as a crowbar", wrong: "A policy denies a legitimate server operation, so the developer switches that call to the service-role client — and quietly disables every rule for that entire code path.", right: "Fix the policy (that's its job), or — if the operation is genuinely above the rules (backups, admin tooling) — isolate the service-role call behind a small, reviewed server function that does exactly one thing.", explain: "Service-role calls don't run your policies at all: any bug in that path is a total bypass. The discipline: service role is for the few operations that are above the law, wrapped tightly — never for the many that merely failed to read it." },
    { t: "note", kind: "security", title: "The matrix runs in CI or it doesn't exist", text: ["Policies change with every feature; memory of 'we tested it once' does not survive the next sprint. The four-cell suite per table belongs in CI against a fresh migrated database — it's fast (it's just queries) and it converts the silent failure class into a red build. Teams that add this suite report the same thing: the first run finds something. That first finding is the suite paying for itself."], },
    { t: "note", kind: "production", title: "Auditing who saw what", text: ["Because every query runs as a real role with a real user id, audit logging is honest by construction: log the actor (auth.uid()) and the operation in a trigger or an edge function, and 'who touched row 7' is a query, not a guess. Combine with the admins-table pattern and support tools can be granted narrowly (SELECT-only policies for the support role) instead of handing over the service key."], },
    { t: "try", title: "Try it yourself", steps: ["Write the full four-cell matrix for your tasks table as a real test file with two local users — including the positive control — and make it pass.", "Break a policy on purpose (drop the WITH CHECK on update), rerun the suite, and identify which cell catches it. Then fix it and watch the suite go green.", "Add the avatars storage policies; as user A try to upload into user B's folder via a handcrafted path. Confirm the refusal comes from the database, not your client.", "Stretch: add a support role pattern (a table + a SELECT-only policy for that role) and a test proving support can read but never write."], },
    { t: "quiz", title: "Check your understanding", questions: [
      { id: "q1", type: "single", prompt: "Why is the over-grant failure class the dangerous one?", options: ["it throws errors that crash the app", "it is silent — wrong rows simply appear for whoever asks, so only an adversarial test finds it", "it only affects anonymous users", "it corrupts the data"], answer: [1], explain: "Over-denial breaks features loudly (tickets). Over-grant breaks confidentiality silently (incidents). The matrix exists because nothing else hunts the silent class.", tags: ["rls-testing-discipline"] },
      { id: "q2", type: "single", prompt: "In the matrix, 'user A updates user B's row' is asserted by checking…", options: ["the HTTP status code is 500", "the returned row count after the update is zero — the USING clause rejected the target", "that an exception is thrown", "the service-role logs"], answer: [1], explain: "PostgREST filters rather than refuses: a rejected update touches zero rows and returns zero rows with .select(). Assert on that emptiness — it is the refusal, expressed as data.", tags: ["rls-testing-discipline"] },
      { id: "q3", type: "single", prompt: "A logged-in user suddenly sees an empty list everywhere, no errors, data intact. The fastest diagnostic is…", options: ["redeploy the client", "set role authenticated in the SQL editor and run the same select the client runs — then diff recent policy migrations", "clear the user's cache", "check the connection pool"], answer: [1], explain: "Become the role, run the query, see the denial exactly as the client sees it; then read the recent policy diff for a broken expression (the type-mismatch lab). Policies fail by denying, so reproduce at the policy layer.", tags: ["rls-testing-discipline", "rls-first-principles"] },
      { id: "q4", type: "single", prompt: "The storage policy (storage.foldername(name))[1] = auth.uid()::text enforces…", options: ["file size limits", "that uploads land only under the uploader's own top-level folder — the path convention as a database law", "virus scanning", "public read access"], answer: [1], explain: "The ${user.id}/… path convention becomes checkable SQL: the first folder segment must equal the caller's id. A client trying another user's folder is refused by the database, not by convention.", tags: ["rls-testing-discipline", "supabase-auth-storage"] },
      { id: "q5", type: "boolean", prompt: "Realtime subscribers can receive change events for rows they cannot SELECT.", options: ["True", "False"], answer: [1], explain: "False — realtime delivery is gated by the same RLS policies as SELECT. The publication opts the table in; the subscriber's role and the row's policy decide delivery.", tags: ["rls-testing-discipline", "supabase-auth-storage"] },
      { id: "q6", type: "multi", prompt: "Select ALL legitimate uses of the service role.", options: ["database backups and bulk admin jobs from trusted servers", "wrapping one tightly-reviewed 'above the law' operation in a server function", "making a failing feature work by bypassing the policy on the client", "CI tests that impersonate regular users"], answer: [0, 1], explain: "Service role is for operations genuinely above the rules, server-side and tightly scoped. Using it to silence a policy bug removes every rule from that path — and CI tests impersonate users precisely to exercise the rules, not to skip them.", tags: ["rls-testing-discipline"] },
    ] },
    { t: "vocab", terms: [["Authorization matrix", "The per-table four-cell test: A-reads-B, A-writes-B, anon-reads, anon-writes — plus owner positive controls."], ["Over-grant", "A policy too permissive; silent; found only by adversarial tests."], ["Over-denial", "A policy too strict; loud; debugged via the role loop, never by disabling RLS."], ["Role impersonation", "Testing as real roles — user sessions and (server-side) service role — instead of as the app."], ["Storage policy", "RLS-language rules over storage.objects; folder paths as enforceable law."], ["Policy debug loop", "set role, run the client's query, read the policy as a WHERE clause, diff recent migrations."]] },
    { t: "recap", items: ["Policies are contracts: the four-cell matrix per table, run as real roles, in CI.", "Denied reads return empty — assert on data, and remember only the matrix hunts over-grants.", "Over-denial debugs via the SQL-editor role loop and migration diffs; never by disabling RLS.", "Storage and realtime obey the same identity and rules: folder paths and SELECT rights as law.", "Service role is a wrapped, audited, server-only exception — never a crowbar for a failing policy."] },
    { t: "checkpoint", text: "Write the four matrix cells for any table from memory — as test names, not prose — and state what a denied read returns and why that makes over-grants silent. Both clean? Volume VI is yours: take the gauntlet." },
    { t: "bridge", text: "Identity, rooms, house rules, and the drills that prove them — Volume VI is complete. The cumulative gauntlet spans both modules; pass it and the Supabase phase is certified. Next volume puts all of it behind the framework: Next.js, where server and client components decide which keys and which queries live where.", next: "battle-gauntlet-m6" },
  ],
};

